examples.code_or_diagram:
// MONGODB (denormalized)
db.lessons.insertOne({
  _id: ObjectId(),
  title: "Algoritmos",
  module: { id: ObjectId(), name: "Estruturas" },
  questions: [
    { id: ObjectId(), text: "O que é recursão?" },
    { id: ObjectId(), text: "Exemplos?" }
  ]
});
// 1 documento, 1 query traz tudo

// SQL (normalized)
INSERT INTO lessons VALUES (id, "Algoritmos");
INSERT INTO modules VALUES (moduleId, "Estruturas");
INSERT INTO questions VALUES (qId1, lessonId, "O que é recursão?");
INSERT INTO questions VALUES (qId2, lessonId, "Exemplos?");
-- 4 inserts, queries precisam de JOINs

// Atômico: tudo acontece ou nada
db.userProgress.updateOne(
  { userId: "user1", lessonId: "lesson1" },
  {
    $set: { status: "completed" },
    $inc: { progressPercentage: 100 },
    $currentDate: { completedAt: true }
  }
);
// Sem transação, mas garantido: ou todas mudanças ou nenhuma

// Não atômico: múltiplos documentos
db.users.updateOne({ _id: "user1" }, { $inc: { completedLessons: 1 } });
db.lessons.updateOne({ _id: "lesson1" }, { $inc: { completions: 1 } });
// Se falhar entre, inconsistência

// DENORMALIZADO: Lê rápido, atualiza caro
db.userProgress.insertOne({
  userId: "user1",
  lesson: { id, title, module, difficulty }, // Dados embebidos
  answers: [{ questionId, isCorrect }, ...]
});
// Query: db.userProgress.findOne({ userId }); traz tudo
// Atualizar lesson: updateMany multidocs

// NORMALIZADO: Lê com lookup, atualiza rápido
db.userProgress.insertOne({ userId, lessonId }); // Apenas ref
db.lessons.insertOne({ _id, title, module, difficulty });
// Query: agregação com $lookup (join)
// Atualizar lesson: um documento

// Índice em coluna de busca
db.users.createIndex({ email: 1 });
db.users.findOne({ email }); // Index scan, rápido

// Índice composto
db.userProgress.createIndex({ userId: 1, status: 1 });
db.userProgress.find({ userId, status }); // Compound index

// Full-text index
db.lessons.createIndex({ title: "text", content: "text" });
db.lessons.find({ $text: { $search: "algoritmo" } }); // Text search
